import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:flutter/services.dart';

import '../archive_api.dart' show flattenFolders;
import '../archive_backend.dart';
import '../archive_capabilities.dart';
import '../archive_errors.dart';
import '../archive_models.dart';
import '../attachment_download.dart';
import '../search_filters.dart';

/// Bundled fictional archive, generated by tools/generate_demo_archive.py.
const demoArchiveAsset = 'assets/demo/archive.json';
const demoAttachmentDirectory = 'assets/demo/attachments';

/// The demo's display address. `.invalid` is reserved and can never resolve,
/// and [DemoArchive] never opens a network connection to it anyway.
final demoServer = Uri.parse('https://demo.mailburrow.invalid');

const _pageSize = 25;

/// An in-app archive of fictional sample mail for demo mode.
///
/// Implements [ArchiveBackend] entirely from bundled assets: it makes no
/// network requests, stores nothing and is never saved as a connection.
/// Search, folders, filters, sorting and paging run in memory and return the
/// same JSON shapes as Mail-Archiver, so every screen behaves as it would
/// with a real server. Attachments are copied from bundled files through the
/// normal save flow.
class DemoArchive implements ArchiveBackend {
  DemoArchive._(Map<String, dynamic> data, this._bundle, this._latency)
    : _accounts = (data['accounts'] as List<dynamic>)
          .cast<Map<String, dynamic>>(),
      _folders = data['folders'] as Map<String, dynamic>,
      _messages = (data['messages'] as List<dynamic>)
          .cast<Map<String, dynamic>>(),
      _attachmentFiles = (data['attachmentFiles'] as Map<String, dynamic>)
          .cast<String, String>();

  /// Loads the bundled demo archive. [latency] adds a short pause to list
  /// and search results so loading states appear as they would with a
  /// server; tests pass [Duration.zero].
  static Future<DemoArchive> load({
    AssetBundle? bundle,
    Duration latency = const Duration(milliseconds: 250),
  }) async {
    final source = bundle ?? rootBundle;
    final text = await source.loadString(demoArchiveAsset, cache: false);
    return DemoArchive.parse(text, bundle: source, latency: latency);
  }

  /// Builds a demo archive from already-loaded archive JSON. Attachments are
  /// still read from [bundle] when saved. Widget tests use this to avoid
  /// asset I/O inside the fake test clock.
  static DemoArchive parse(
    String archiveJson, {
    AssetBundle? bundle,
    Duration latency = const Duration(milliseconds: 250),
  }) => DemoArchive._(
    jsonDecode(archiveJson) as Map<String, dynamic>,
    bundle ?? rootBundle,
    latency,
  );

  final AssetBundle _bundle;
  final Duration _latency;
  final List<Map<String, dynamic>> _accounts;
  final Map<String, dynamic> _folders;
  final List<Map<String, dynamic>> _messages;
  final Map<String, String> _attachmentFiles;
  bool _closed = false;
  final _transfers = <AttachmentDownload>{};

  @override
  Uri get server => demoServer;

  /// Never sent anywhere; present only because the interface requires it.
  @override
  String get key => 'demo';

  @override
  ArchiveCapabilities get capabilities => ArchiveCapabilities.full;

  void _checkOpen() {
    if (_closed) throw StateError('Demo archive closed');
  }

  Future<void> _pause() async {
    if (_latency > Duration.zero) await Future<void>.delayed(_latency);
    _checkOpen();
  }

  @override
  Future<List<ArchiveAccount>> accounts() async {
    _checkOpen();
    return [for (final account in _accounts) ArchiveAccount.fromJson(account)];
  }

  @override
  Future<List<ArchiveFolder>> folders(String accountId) async {
    _checkOpen();
    final tree = _folders[accountId] as List<dynamic>?;
    if (tree == null) throw const ArchiveFailure(404);
    return flattenFolders(tree);
  }

  @override
  Future<MailPage> emails(
    String accountId,
    String query,
    int page, {
    String? folder,
    SearchFilters filters = const SearchFilters(),
  }) async {
    await _pause();
    if (!_accounts.any((account) => account['id'].toString() == accountId)) {
      throw const ArchiveFailure(404);
    }
    final needle = query.trim().toLowerCase();
    final from = filters.from == null ? null : dateLabel(filters.from!);
    final to = filters.to == null ? null : dateLabel(filters.to!);
    final matches = _messages.where((mail) {
      if (mail['accountId'].toString() != accountId) return false;
      if (folder != null && mail['folderName'] != folder) return false;
      if (filters.direction == 'incoming' && mail['isOutgoing'] == true) {
        return false;
      }
      if (filters.direction == 'outgoing' && mail['isOutgoing'] != true) {
        return false;
      }
      if (from != null || to != null) {
        final sent = mail['sentDate'] as String? ?? '';
        if (sent.length < 10) return false;
        final day = sent.substring(0, 10);
        if (from != null && day.compareTo(from) < 0) return false;
        if (to != null && day.compareTo(to) > 0) return false;
      }
      if (needle.isEmpty) return true;
      return [
        mail['subject'],
        mail['from'],
        mail['to'],
        mail['textBody'],
      ].any((field) => (field as String? ?? '').toLowerCase().contains(needle));
    }).toList();
    String sortValue(Map<String, dynamic> mail) =>
        (mail[switch (filters.sortBy) {
                      'receivedDate' => 'receivedDate',
                      'subject' => 'subject',
                      'from' => 'from',
                      'to' => 'to',
                      _ => 'sentDate',
                    }]
                    as String? ??
                '')
            .toLowerCase();
    final descending = filters.sortOrder != 'asc';
    matches.sort((a, b) {
      final order = sortValue(a).compareTo(sortValue(b));
      final result = order != 0
          ? order
          : (a['id'] as int).compareTo(b['id'] as int);
      return descending ? -result : result;
    });
    final totalItems = matches.length;
    final totalPages = (totalItems + _pageSize - 1) ~/ _pageSize;
    final start = (math.max(page, 1) - 1) * _pageSize;
    return MailPage(
      items: [
        for (final mail in matches.skip(start).take(_pageSize))
          MailSummary.fromJson(mail),
      ],
      page: page,
      totalPages: totalPages,
      totalItems: totalItems,
    );
  }

  Map<String, dynamic>? _find(String id) =>
      _messages.where((mail) => mail['id'].toString() == id).firstOrNull;

  @override
  Future<MailMessage> message(String id) async {
    _checkOpen();
    final mail = _find(id);
    if (mail == null) throw const ArchiveFailure(404);
    return MailMessage.fromJson(mail);
  }

  @override
  Future<void> downloadAttachment(
    String emailId,
    String attachmentId,
    File destination, {
    AttachmentDownload? transfer,
    void Function(int receivedBytes)? onProgress,
  }) async {
    _checkOpen();
    final mail = _find(emailId);
    final belongs = (mail?['attachments'] as List<dynamic>? ?? []).any(
      (file) => (file as Map<String, dynamic>)['id'].toString() == attachmentId,
    );
    final name = _attachmentFiles[attachmentId];
    if (!belongs || name == null) throw const ArchiveFailure(404);
    final active = transfer ?? AttachmentDownload();
    active.throwIfStopped();
    // Registered so close() can stop this copy between chunks.
    _transfers.add(active);
    RandomAccessFile? output;
    var opened = false, completed = false;
    try {
      final data = await active.wait(
        _bundle.load('$demoAttachmentDirectory/$name'),
      );
      final bytes = Uint8List.sublistView(data);
      if (bytes.length > maxAttachmentDownloadBytes) {
        throw const AttachmentTooLarge();
      }
      active.throwIfStopped();
      output = await destination.open(mode: FileMode.write);
      opened = true;
      const chunk = 256;
      var received = 0;
      while (received < bytes.length) {
        active.throwIfStopped();
        final end = math.min(received + chunk, bytes.length);
        await output.writeFrom(bytes, received, end);
        // A cancel or close during the write stops here: no further writes
        // or progress callbacks.
        active.throwIfStopped();
        received = end;
        onProgress?.call(received);
        if (_latency > Duration.zero) {
          await active.wait(Future<void>.delayed(_latency ~/ 5));
        }
      }
      await output.flush();
      await output.close();
      output = null;
      active.throwIfStopped();
      _checkOpen();
      completed = true;
    } finally {
      _transfers.remove(active);
      if (output != null) {
        try {
          await output.close();
        } catch (_) {}
      }
      if (opened && !completed) {
        try {
          await destination.delete();
        } catch (_) {
          // The caller also attempts private temporary-directory cleanup.
        }
      }
    }
  }

  @override
  Future<ArchiveStats> stats() async {
    _checkOpen();
    return ArchiveStats(
      _messages.length,
      _accounts.length,
      _messages.fold<int>(
        0,
        (total, mail) => total + (mail['attachments'] as List<dynamic>).length,
      ),
    );
  }

  /// Nothing to cancel: results are computed locally, and the session already
  /// ignores responses from superseded requests.
  @override
  void cancelEmailRequests() {}

  /// Refuses new requests and stops attachment copies in progress; their
  /// partial files are deleted.
  @override
  void close() {
    _closed = true;
    for (final transfer in _transfers.toList()) {
      transfer.cancel();
    }
  }
}
